@Test
public void testStandardColumnCompactions() {
    // this test does enough rows to force multiple block indexes to be used
    Keyspace keyspace = Keyspace.open(KEYSPACE1);
    ColumnFamilyStore cfs = keyspace.getColumnFamilyStore("Standard1");
    cfs.clearUnsafe();
    final int ROWS_PER_SSTABLE = 10;
    final int SSTABLES = cfs.metadata.params.minIndexInterval * 3 / ROWS_PER_SSTABLE;
    // disable compaction while flushing
    cfs.disableAutoCompaction();
    long maxTimestampExpected = Long.MIN_VALUE;
    Set<DecoratedKey> inserted = new HashSet<DecoratedKey>();
    for (int j = 0; j < SSTABLES; j++) {
        for (int i = 0; i < ROWS_PER_SSTABLE; i++) {
            DecoratedKey key = Util.dk(String.valueOf(i % 2));
            long timestamp = j * ROWS_PER_SSTABLE + i;
            maxTimestampExpected = Math.max(timestamp, maxTimestampExpected);
            UpdateBuilder.create(cfs.metadata, key).withTimestamp(timestamp).newRow(String.valueOf(i / 2)).add("val", ByteBufferUtil.EMPTY_BYTE_BUFFER).apply();
            inserted.add(key);
        }
        cfs.forceBlockingFlush();
        CompactionsTest.assertMaxTimestamp(cfs, maxTimestampExpected);
        assertEquals(inserted.toString(), inserted.size(), Util.getAll(Util.cmd(cfs).build()).size());
    }
    forceCompactions(cfs);
    assertEquals(inserted.toString(), inserted.size(), Util.getAll(Util.cmd(cfs).build()).size());
    // make sure max timestamp of compacted sstables is recorded properly after compaction.
    CompactionsTest.assertMaxTimestamp(cfs, maxTimestampExpected);
    cfs.truncateBlocking();
}

@Test
public void testParallelLeveledCompaction() throws Exception {
    String ksname = KEYSPACE1;
    String cfname = "StandardLeveled";
    Keyspace keyspace = Keyspace.open(ksname);
    ColumnFamilyStore store = keyspace.getColumnFamilyStore(cfname);
    store.disableAutoCompaction();
    CompactionStrategyManager mgr = store.getCompactionStrategyManager();
    LeveledCompactionStrategy lcs = (LeveledCompactionStrategy) mgr.getStrategies().get(1).get(0);
    // 100 KB value, make it easy to have multiple files
    ByteBuffer value = ByteBuffer.wrap(new byte[100 * 1024]);
    // Enough data to have a level 1 and 2
    int rows = 128;
    int columns = 10;
    // Adds enough data to trigger multiple sstable per level
    for (int r = 0; r < rows; r++) {
        DecoratedKey key = Util.dk(String.valueOf(r));
        UpdateBuilder builder = UpdateBuilder.create(store.metadata, key);
        for (int c = 0; c < columns; c++) builder.newRow("column" + c).add("val", value);
        Mutation rm = new Mutation(builder.build());
        rm.apply();
        store.forceBlockingFlush();
    }
    // Execute LCS in parallel
    ExecutorService executor = new ThreadPoolExecutor(4, 4, Long.MAX_VALUE, TimeUnit.SECONDS, new LinkedBlockingDeque<Runnable>());
    List<Runnable> tasks = new ArrayList<Runnable>();
    while (true) {
        while (true) {
            final AbstractCompactionTask nextTask = lcs.getNextBackgroundTask(Integer.MIN_VALUE);
            if (nextTask == null)
                break;
            tasks.add(new Runnable() {

                public void run() {
                    nextTask.execute(null);
                }
            });
        }
        if (tasks.isEmpty())
            break;
        List<Future<?>> futures = new ArrayList<Future<?>>(tasks.size());
        for (Runnable r : tasks) futures.add(executor.submit(r));
        FBUtilities.waitOnFutures(futures);
        tasks.clear();
    }
    // Assert all SSTables are lined up correctly.
    LeveledManifest manifest = lcs.manifest;
    int levels = manifest.getLevelCount();
    for (int level = 0; level < levels; level++) {
        List<SSTableReader> sstables = manifest.getLevel(level);
        // score check
        assert (double) SSTableReader.getTotalBytes(sstables) / LeveledManifest.maxBytesForLevel(level, 1 * 1024 * 1024) < 1.00;
        // overlap check for levels greater than 0
        for (SSTableReader sstable : sstables) {
            // level check
            assert level == sstable.getSSTableLevel();
            if (level > 0) {
                // overlap check for levels greater than 0
                Set<SSTableReader> overlaps = LeveledManifest.overlapping(sstable.first.getToken(), sstable.last.getToken(), sstables);
                assert overlaps.size() == 1 && overlaps.contains(sstable);
            }
        }
    }
}

@Test
public void testLeveledScanner() throws Exception {
    Keyspace keyspace = Keyspace.open(KEYSPACE1);
    ColumnFamilyStore store = keyspace.getColumnFamilyStore(CF_STANDARDLVL2);
    // 100 KB value, make it easy to have multiple files
    ByteBuffer value = ByteBuffer.wrap(new byte[100 * 1024]);
    // Enough data to have a level 1 and 2
    int rows = 128;
    int columns = 10;
    // Adds enough data to trigger multiple sstable per level
    for (int r = 0; r < rows; r++) {
        DecoratedKey key = Util.dk(String.valueOf(r));
        UpdateBuilder builder = UpdateBuilder.create(store.metadata, key);
        for (int c = 0; c < columns; c++) builder.newRow("column" + c).add("val", value);
        Mutation rm = new Mutation(builder.build());
        rm.apply();
        store.forceBlockingFlush();
    }
    LeveledCompactionStrategyTest.waitForLeveling(store);
    store.disableAutoCompaction();
    CompactionStrategyManager mgr = store.getCompactionStrategyManager();
    LeveledCompactionStrategy lcs = (LeveledCompactionStrategy) mgr.getStrategies().get(1).get(0);
    // 10 KB value
    value = ByteBuffer.wrap(new byte[10 * 1024]);
    // Adds 10 partitions
    for (int r = 0; r < 10; r++) {
        DecoratedKey key = Util.dk(String.valueOf(r));
        UpdateBuilder builder = UpdateBuilder.create(store.metadata, key);
        for (int c = 0; c < 10; c++) builder.newRow("column" + c).add("val", value);
        Mutation rm = new Mutation(builder.build());
        rm.apply();
    }
    //Flush sstable
    store.forceBlockingFlush();
    Iterable<SSTableReader> allSSTables = store.getSSTables(SSTableSet.LIVE);
    for (SSTableReader sstable : allSSTables) {
        if (sstable.getSSTableLevel() == 0) {
            System.out.println("Mutating L0-SSTABLE level to L1 to simulate a bug: " + sstable.getFilename());
            sstable.descriptor.getMetadataSerializer().mutateLevel(sstable.descriptor, 1);
            sstable.reloadSSTableMetadata();
        }
    }
    try (AbstractCompactionStrategy.ScannerList scannerList = lcs.getScanners(Lists.newArrayList(allSSTables))) {
        //Verify that leveled scanners will always iterate in ascending order (CASSANDRA-9935)
        for (ISSTableScanner scanner : scannerList.scanners) {
            DecoratedKey lastKey = null;
            while (scanner.hasNext()) {
                UnfilteredRowIterator row = scanner.next();
                if (lastKey != null) {
                    assertTrue("row " + row.partitionKey() + " received out of order wrt " + lastKey, row.partitionKey().compareTo(lastKey) >= 0);
                }
                lastKey = row.partitionKey();
            }
        }
    }
}

@Test
public void testExistingCluster() {
    for (int rf = 1; rf <= 5; ++rf) {
        for (int perUnitCount = 1; perUnitCount <= MAX_VNODE_COUNT; perUnitCount *= 4) {
            testExistingCluster(perUnitCount, fixedTokenCount, new SimpleReplicationStrategy(rf));
            testExistingCluster(perUnitCount, varyingTokenCount, new SimpleReplicationStrategy(rf));
            // Replication strategy doesn't matter for RF = 1.
            if (rf == 1)
                continue;
            for (int groupSize = 4; groupSize <= 64 && groupSize * rf * 4 < TARGET_CLUSTER_SIZE; groupSize *= 4) {
                testExistingCluster(perUnitCount, fixedTokenCount, new BalancedGroupReplicationStrategy(rf, groupSize));
                testExistingCluster(perUnitCount, varyingTokenCount, new UnbalancedGroupReplicationStrategy(rf, groupSize / 2, groupSize * 2, seededRand));
            }
            testExistingCluster(perUnitCount, fixedTokenCount, new FixedGroupCountReplicationStrategy(rf, rf * 2));
        }
    }
}

