@Test
public void testWideRow() throws Exception {
    String KS = "cql_keyspace";
    String TABLE = "table1";
    int size = 30000;
    File tempdir = Files.createTempDir();
    File dataDir = new File(tempdir.getAbsolutePath() + File.separator + KS + File.separator + TABLE);
    assert dataDir.mkdirs();
    StringBuilder schemaColumns = new StringBuilder();
    StringBuilder queryColumns = new StringBuilder();
    StringBuilder queryValues = new StringBuilder();
    for (int i = 0; i < size; i++) {
        schemaColumns.append("v");
        schemaColumns.append(i);
        schemaColumns.append(" int,");
        queryColumns.append(", v");
        queryColumns.append(i);
        queryValues.append(", ?");
    }
    String schema = "CREATE TABLE cql_keyspace.table1 (" + "  k int," + "  c int," + schemaColumns.toString() + "  PRIMARY KEY (k, c)" + ")";
    String insert = "INSERT INTO cql_keyspace.table1 (k, c" + queryColumns.toString() + ") VALUES (?, ?" + queryValues.toString() + ")";
    CQLSSTableWriter writer = CQLSSTableWriter.builder().inDirectory(dataDir).forTable(schema).using(insert).withBufferSizeInMB(1).build();
    long high = 100;
    Random r = new Random(0);
    for (int i = 0; i < high; i++) {
        List<Object> values = new ArrayList<>(size + 2);
        values.add(0);
        values.add(r.nextInt());
        for (int j = 0; j < size; j++) {
            values.add(i);
        }
        writer.addRow(values);
    }
    writer.close();
}

@Test
public void testConcurrency() throws InterruptedException, IOException, ConfigurationException {
    // The goal of this test is to check for CASSANDRA-8448/CASSANDRA-9519
    double badness = DatabaseDescriptor.getDynamicBadnessThreshold();
    DatabaseDescriptor.setDynamicBadnessThreshold(0.0);
    try {
        final int ITERATIONS = 10000;
        // do this because SS needs to be initialized before DES can work properly.
        StorageService.instance.unsafeInitialize();
        SimpleSnitch ss = new SimpleSnitch();
        DynamicEndpointSnitch dsnitch = new DynamicEndpointSnitch(ss, String.valueOf(ss.hashCode()));
        InetAddress self = FBUtilities.getBroadcastAddress();
        List<InetAddress> hosts = new ArrayList<>();
        // We want a big list of hosts so  sorting takes time, making it much more likely to reproduce the
        // problem we're looking for.
        for (int i = 0; i < 100; i++) for (int j = 0; j < 256; j++) hosts.add(InetAddress.getByAddress(new byte[] { 127, 0, (byte) i, (byte) j }));
        ScoreUpdater updater = new ScoreUpdater(dsnitch, hosts);
        updater.start();
        List<InetAddress> result = null;
        for (int i = 0; i < ITERATIONS; i++) result = dsnitch.getSortedListByProximity(self, hosts);
        updater.stopped = true;
        updater.join();
    } finally {
        DatabaseDescriptor.setDynamicBadnessThreshold(badness);
    }
}

@Test
public void testCompressedStream() throws InvalidRequestException, IOException, ExecutionException, InterruptedException {
    String KS = "cql_keyspace";
    String TABLE = "table1";
    File tempdir = Files.createTempDir();
    File dataDir = new File(tempdir.getAbsolutePath() + File.separator + KS + File.separator + TABLE);
    assert dataDir.mkdirs();
    String schema = "CREATE TABLE cql_keyspace.table1 (" + "  k int PRIMARY KEY," + "  v1 text," + "  v2 int" + // with compression = {};";
    ");";
    String insert = "INSERT INTO cql_keyspace.table1 (k, v1, v2) VALUES (?, ?, ?)";
    CQLSSTableWriter writer = CQLSSTableWriter.builder().sorted().inDirectory(dataDir).forTable(schema).using(insert).build();
    long start = System.nanoTime();
    for (int i = 0; i < 10_000_000; i++) writer.addRow(i, "test1", 24);
    writer.close();
    System.err.println(String.format("Writer finished after %d seconds....", TimeUnit.NANOSECONDS.toSeconds(System.nanoTime() - start)));
    File[] dataFiles = dataDir.listFiles((dir, name) -> name.endsWith("-Data.db"));
    long dataSize = 0l;
    for (File file : dataFiles) {
        System.err.println("File : " + file.getAbsolutePath());
        dataSize += file.length();
    }
    SSTableLoader loader = new SSTableLoader(dataDir, new SSTableLoader.Client() {

        private String ks;

        public void init(String keyspace) {
            for (Range<Token> range : StorageService.instance.getLocalRanges("cql_keyspace")) addRangeForEndpoint(range, FBUtilities.getBroadcastAddress());
            this.ks = keyspace;
        }

        public CFMetaData getTableMetadata(String cfName) {
            return Schema.instance.getCFMetaData(ks, cfName);
        }
    }, new OutputHandler.SystemOutput(false, false));
    start = System.nanoTime();
    loader.stream().get();
    long millis = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
    System.err.println(String.format("Finished Streaming in %.2f seconds: %.2f Mb/sec", millis / 1000d, (dataSize / (1 << 20) / (millis / 1000d)) * 8));
    //Stream again
    loader = new SSTableLoader(dataDir, new SSTableLoader.Client() {

        private String ks;

        public void init(String keyspace) {
            for (Range<Token> range : StorageService.instance.getLocalRanges("cql_keyspace")) addRangeForEndpoint(range, FBUtilities.getBroadcastAddress());
            this.ks = keyspace;
        }

        public CFMetaData getTableMetadata(String cfName) {
            return Schema.instance.getCFMetaData(ks, cfName);
        }
    }, new OutputHandler.SystemOutput(false, false));
    start = System.nanoTime();
    loader.stream().get();
    millis = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
    System.err.println(String.format("Finished Streaming in %.2f seconds: %.2f Mb/sec", millis / 1000d, (dataSize / (1 << 20) / (millis / 1000d)) * 8));
    //Compact them both
    start = System.nanoTime();
    Keyspace.open(KS).getColumnFamilyStore(TABLE).forceMajorCompaction();
    millis = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
    System.err.println(String.format("Finished Compacting in %.2f seconds: %.2f Mb/sec", millis / 1000d, (dataSize * 2 / (1 << 20) / (millis / 1000d)) * 8));
    UntypedResultSet rs = QueryProcessor.executeInternal("SELECT * FROM cql_keyspace.table1 limit 100;");
    assertEquals(100, rs.size());
}

