public void testAlterNonFrozenUDT() throws Throwable {
    String myType = KEYSPACE + '.' + createType("CREATE TYPE %s (a int, b text)");
    createTable("CREATE TABLE %s (k int PRIMARY KEY, v " + myType + ")");
