    type1 = createType("CREATE TYPE %s (foo ascii)");
    String type2 = createType("CREATE TYPE %s (foo frozen<" + type1 + ">)");
    assertComplexInvalidAlterDropStatements(type1, type2, "{foo: {foo: 'abc'}}");
