@Test
public void filteringOnClusteringColumns() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, c int, d int, PRIMARY KEY (a, b, c))");
    execute("INSERT INTO %s (a,b,c,d) VALUES (11, 12, 13, 14)");
    execute("INSERT INTO %s (a,b,c,d) VALUES (11, 15, 16, 17)");
    execute("INSERT INTO %s (a,b,c,d) VALUES (21, 22, 23, 24)");
    execute("INSERT INTO %s (a,b,c,d) VALUES (31, 32, 33, 34)");
    beforeAndAfterFlush(() -> {
        assertRows(execute("SELECT * FROM %s WHERE a = 11 AND b = 15"), row(11, 15, 16, 17));
        assertInvalidMessage("Clustering column \"c\" cannot be restricted (preceding column \"b\" is restricted by a non-EQ relation)", "SELECT * FROM %s WHERE a = 11 AND b > 12 AND c = 15");
        assertRows(execute("SELECT * FROM %s WHERE a = 11 AND b = 15 AND c > 15"), row(11, 15, 16, 17));
        assertRows(execute("SELECT * FROM %s WHERE a = 11 AND b > 12 AND c > 13 AND d = 17 ALLOW FILTERING"), row(11, 15, 16, 17));
        assertInvalidMessage("Clustering column \"c\" cannot be restricted (preceding column \"b\" is restricted by a non-EQ relation)", "SELECT * FROM %s WHERE a = 11 AND b > 12 AND c > 13 and d = 17");
        assertRows(execute("SELECT * FROM %s WHERE b > 20 AND c > 30 ALLOW FILTERING"), row(31, 32, 33, 34));
        assertInvalidMessage("Clustering column \"c\" cannot be restricted (preceding column \"b\" is restricted by a non-EQ relation)", "SELECT * FROM %s WHERE b > 20 AND c > 30");
        assertRows(execute("SELECT * FROM %s WHERE b > 20 AND c < 30 ALLOW FILTERING"), row(21, 22, 23, 24));
        assertInvalidMessage("Clustering column \"c\" cannot be restricted (preceding column \"b\" is restricted by a non-EQ relation)", "SELECT * FROM %s WHERE b > 20 AND c < 30");
