@Test
public void testRangeTombstone() throws Throwable {
    createTable("CREATE TABLE %s (" + "k int, " + "asciival ascii, " + "bigintval bigint, " + "textval1 text, " + "textval2 text, " + "PRIMARY KEY((k, asciival), bigintval, textval1)" + ")");
