        Util.assertEmpty(Util.cmd(cfs, "0").columns("c").withLimit(0).build());
        // slice with nothing in between the bounds
        Util.assertEmpty(Util.cmd(cfs, "0").columns("c").fromIncl(1).toIncl(1).build());
