    Cell r1m2 = BufferCell.live(m, ts1, BB2, CellPath.create(BB2));
    List<Cell> r1ExpectedCells = Lists.newArrayList(r1v, r1m1, r1m2);
    r1ExpectedCells.forEach(r1Builder::addCell);
