@Test
public void testCustomIndexExpressionSyntax() throws Throwable {
    Object[] row = row(0, 0, 0, 0);
    createTable("CREATE TABLE %s (a int, b int, c int, d int, PRIMARY KEY (a, b))");
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", row);
    assertInvalidMessage(String.format(IndexRestrictions.INDEX_NOT_FOUND, "custom_index", keyspace(), currentTable()), "SELECT * FROM %s WHERE expr(custom_index, 'foo bar baz')");
    createIndex(String.format("CREATE CUSTOM INDEX custom_index ON %%s(c) USING '%s'", StubIndex.class.getName()));
    assertInvalidThrowMessage(Server.CURRENT_VERSION, String.format(IndexRestrictions.INDEX_NOT_FOUND, "no_such_index", keyspace(), currentTable()), QueryValidationException.class, "SELECT * FROM %s WHERE expr(no_such_index, 'foo bar baz ')");
    // simple case
    assertRows(execute("SELECT * FROM %s WHERE expr(custom_index, 'foo bar baz')"), row);
    assertRows(execute("SELECT * FROM %s WHERE expr(\"custom_index\", 'foo bar baz')"), row);
    assertRows(execute("SELECT * FROM %s WHERE expr(custom_index, $$foo \" ~~~ bar Baz$$)"), row);
    // multiple expressions on the same index
    assertInvalidThrowMessage(Server.CURRENT_VERSION, IndexRestrictions.MULTIPLE_EXPRESSIONS, QueryValidationException.class, "SELECT * FROM %s WHERE expr(custom_index, 'foo') AND expr(custom_index, 'bar')");
    // multiple expressions on different indexes
    createIndex(String.format("CREATE CUSTOM INDEX other_custom_index ON %%s(d) USING '%s'", StubIndex.class.getName()));
    assertInvalidThrowMessage(Server.CURRENT_VERSION, IndexRestrictions.MULTIPLE_EXPRESSIONS, QueryValidationException.class, "SELECT * FROM %s WHERE expr(custom_index, 'foo') AND expr(other_custom_index, 'bar')");
    assertInvalidThrowMessage(Server.CURRENT_VERSION, StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, QueryValidationException.class, "SELECT * FROM %s WHERE expr(custom_index, 'foo') AND d=0");
    assertRows(execute("SELECT * FROM %s WHERE expr(custom_index, 'foo') AND d=0 ALLOW FILTERING"), row);
}

