public void customExpressionForcesIndexSelection() throws Throwable {
    createTable("CREATE TABLE %s(a int, b int, c int, PRIMARY KEY (a))");
    createIndex(String.format("CREATE CUSTOM INDEX %s_more_selective ON %%s(b) USING '%s'", currentTable(), SettableSelectivityIndex.class.getName()));
    createIndex(String.format("CREATE CUSTOM INDEX %s_less_selective ON %%s(c) USING '%s'", currentTable(), SettableSelectivityIndex.class.getName()));
    SettableSelectivityIndex moreSelective = (SettableSelectivityIndex) getCurrentColumnFamilyStore().indexManager.getIndexByName(currentTable() + "_more_selective");
    SettableSelectivityIndex lessSelective = (SettableSelectivityIndex) getCurrentColumnFamilyStore().indexManager.getIndexByName(currentTable() + "_less_selective");
    assertEquals(0, moreSelective.searchersProvided);
    assertEquals(0, lessSelective.searchersProvided);
    // without a custom expression, the more selective index should be chosen
    moreSelective.setEstimatedResultRows(1);
    lessSelective.setEstimatedResultRows(1000);
    execute("SELECT * FROM %s WHERE b=0 AND c=0 ALLOW FILTERING");
    assertEquals(1, moreSelective.searchersProvided);
    assertEquals(0, lessSelective.searchersProvided);
    // when a custom expression is present, its target index should be preferred
    execute(String.format("SELECT * FROM %%s WHERE b=0 AND expr(%s_less_selective, 'expression') ALLOW FILTERING", currentTable()));
    assertEquals(1, moreSelective.searchersProvided);
    assertEquals(1, lessSelective.searchersProvided);
}

@Test
public void testCustomExpressionValueType() throws Throwable {
    // verify that the type of the expression value is determined by Index::customExpressionValueType
    createTable("CREATE TABLE %s (k int, v1 uuid, v2 blob, PRIMARY KEY(k))");
    createIndex(String.format("CREATE CUSTOM INDEX int_index ON %%s() USING '%s'", Int32ExpressionIndex.class.getName()));
    createIndex(String.format("CREATE CUSTOM INDEX text_index ON %%s() USING '%s'", UTF8ExpressionIndex.class.getName()));
    execute("SELECT * FROM %s WHERE expr(text_index, 'foo')");
    assertInvalidThrowMessage(Server.CURRENT_VERSION, "Invalid INTEGER constant (99) for \"custom index expression\" of type text", QueryValidationException.class, "SELECT * FROM %s WHERE expr(text_index, 99)");
    execute("SELECT * FROM %s WHERE expr(int_index, 99)");
    assertInvalidThrowMessage(Server.CURRENT_VERSION, "Invalid STRING constant (foo) for \"custom index expression\" of type int", QueryValidationException.class, "SELECT * FROM %s WHERE expr(int_index, 'foo')");
}

