    try (RewindableDataInputStreamPlus reader = new RewindableDataInputStreamPlus(new ByteArrayInputStream(testData), INITIAL_BUFFER_SIZE, Integer.MAX_VALUE, file, Integer.MAX_VALUE)) {
        reader.mark();
        assertEquals("abc", reader.readUTF());
        reader.reset();
        assertEquals("abc", reader.readUTF());
    }
    assertFalse(file.exists());
    baos = new ByteArrayOutputStream();
    try (DataOutputStream out = new DataOutputStream(baos)) {
        out.writeBoolean(true);
        out.writeBoolean(true);
        testData = baos.toByteArray();
    }
}

@Test
public void testMarkAndResetBigBuffer() throws Exception {
    byte[] testData;
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    try (DataOutputStream out = new DataOutputStream(baos)) {
        // boolean
        out.writeBoolean(true);
        // byte
        out.writeByte(0x1);
        // char
        out.writeChar('a');
        // short
        out.writeShort(1);
        // int
        out.writeInt(1);
        // long
        out.writeLong(1L);
        // float
        out.writeFloat(1.0f);
        // double
        out.writeDouble(1.0d);
        // String
        out.writeUTF("abc");
        testData = baos.toByteArray();
        // 1 (boolean) + 1 (byte) + 2 (char) + 2 (short) + 4 (int) + 8 (long)
        // + 4 (float) + 8 (double) + 5 bytes (utf string)
    }
    for (int memCapacity = 0; memCapacity <= 18; memCapacity++) {
        int diskCapacity = 18 - memCapacity;
        try (RewindableDataInputStreamPlus reader = new RewindableDataInputStreamPlus(new ByteArrayInputStream(testData), INITIAL_BUFFER_SIZE, memCapacity, file, diskCapacity)) {
            //read a big amount before resetting
            reader.mark();
            assertTrue(reader.readBoolean());
            assertEquals(0x1, reader.readByte());
            assertEquals('a', reader.readChar());
            assertEquals(1, reader.readShort());
            assertEquals(1, reader.readInt());
            assertEquals(1L, reader.readLong());
            reader.reset();
            //read from buffer
            assertTrue(reader.readBoolean());
            assertEquals(0x1, reader.readByte());
            assertEquals('a', reader.readChar());
            assertEquals(1, reader.readShort());
            assertEquals(1, reader.readInt());
            assertEquals(1L, reader.readLong());
            assertEquals(17, reader.available());
            //mark again
            reader.mark();
            assertEquals(1.0f, reader.readFloat(), 0);
            assertEquals(1.0d, reader.readDouble(), 0);
            assertEquals("abc", reader.readUTF());
            reader.reset();
            assertEquals(17, reader.available());
            assertEquals(1.0f, reader.readFloat(), 0);
            assertEquals(1.0d, reader.readDouble(), 0);
            assertEquals("abc", reader.readUTF());
        }
        assertFalse(file.exists());
    }
}

@Test
public void testCircularSpillFile() throws Exception {
    byte[] testData;
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    try (DataOutputStream out = new DataOutputStream(baos)) {
        // boolean
        out.writeBoolean(true);
        // byte
        out.writeByte(0x1);
        // char
        out.writeChar('a');
        // short
        out.writeShort(1);
        // int
        out.writeInt(1);
        // String
        out.writeUTF("ab");
        testData = baos.toByteArray();
        // 1 (boolean) + 1 (byte) + 2 (char) + 2 (short) + 4 (int) + 4 bytes (utf string)
    }
    //read at most 4 bytes multiple times (and then check file size)
    int MEM_SIZE = 0;
    int DISK_SIZE = 4;
    try (RewindableDataInputStreamPlus reader = new RewindableDataInputStreamPlus(new ByteArrayInputStream(testData), INITIAL_BUFFER_SIZE, MEM_SIZE, file, DISK_SIZE)) {
        //read 2 bytes and reset
        reader.mark();
        assertTrue(reader.readBoolean());
        assertEquals(0x1, reader.readByte());
        assertEquals(2, reader.bytesPastMark(null));
        reader.reset();
        //read again previous sequence
        assertTrue(reader.readBoolean());
        assertEquals(0x1, reader.readByte());
        //finish reading again previous sequence
        //read 4 bytes and reset
        reader.mark();
        assertEquals('a', reader.readChar());
        assertEquals(1, reader.readShort());
        assertEquals(4, reader.bytesPastMark(null));
        reader.reset();
        //read again previous sequence
        assertEquals('a', reader.readChar());
        assertEquals(1, reader.readShort());
        //finish reading again previous sequence
        //read 4 bytes and reset
        reader.mark();
        assertEquals(1, reader.readInt());
        assertEquals(4, reader.bytesPastMark(null));
        reader.reset();
        //read again previous sequence
        assertEquals(1, reader.readInt());
        //check max file size
        assertEquals(DISK_SIZE, file.length());
    }
    assertFalse(file.exists());
}

