    v1 = new CassandraVersion("1.2.3");
    v2 = new CassandraVersion("1.2.3+foo");
    assertTrue(v1.compareTo(v2) == -1);
    v1 = new CassandraVersion("1.2.3");
    v2 = new CassandraVersion("1.2.3-alpha+foo");
    assertTrue(v1.compareTo(v2) == 1);
    v1 = new CassandraVersion("1.2.3-alpha+1");
