    while (!buffers.isEmpty()) {
        int index = rnd.nextInt(buffers.size());
        ByteBuffer buffer = buffers.remove(index);
        BufferPool.put(buffer);
    }
    assertEquals(null, BufferPool.currentChunk());
    assertEquals(0, chunk.free());
}

